from app.database import db

class Note(db.Model):
    __tablename__ = 'notes'

    id = db.Column(db.Integer, primary_key=True)
    content = db.Column(db.Text, nullable=False)

    def __init__(self, content):
        self.content = content

    def __repr__(self):
        return f'<Note {self.id}: {self.content[:20]}...>'

from flask import Blueprint, render_template, request, redirect, url_for
from app.models.note import Note
from app.database import db

# Define the Blueprint for note-taking routes
notes_bp = Blueprint('notes', __name__, template_folder='templates')

@notes_bp.route('/')
def index():
    # Fetch all notes from the database
    notes = Note.query.all()
    return render_template('index.html', notes=notes)

@notes_bp.route('/add', methods=['POST'])
def add_note():
    # Get the note text from the form data
    note_text = request.form.get('note_text')
    if note_text:
        # Create a new Note object and add it to the database
        new_note = Note(text=note_text)
        db.session.add(new_note)
        db.session.commit()
    return redirect(url_for('notes.index'))

@notes_bp.route('/delete/<int:note_id>', methods=['POST'])
def delete_note(note_id):
    # Find the note by ID and delete it from the database
    note_to_delete = Note.query.get(note_id)
    if note_to_delete:
        db.session.delete(note_to_delete)
        db.session.commit()
    return redirect(url_for('notes.index'))

/* static/styles.css */
/* CSS for styling the note-taking interface */

/* General body styling */
body {
    font-family: Arial, sans-serif;
    background-color: #f9f9f9;
    margin: 0;
    padding: 0;
    line-height: 1.6;
    color: #333;
}

/* Container for the app */
.container {
    max-width: 800px;
    margin: 20px auto;
    padding: 20px;
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

/* Header section */
header {
    text-align: center;
    margin-bottom: 20px;
}

header h1 {
    font-size: 2em;
    color: #444;
}

/* Form styling */
form {
    margin-bottom: 20px;
}

form input[type="text"],
form textarea {
    width: 100%;
    padding: 10px;
    margin-bottom: 10px;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1em;
}

form button {
    background-color: #5cb85c;
    color: #fff;
    border: none;
    padding: 10px 15px;
    border-radius: 4px;
    cursor: pointer;
    font-size: 1em;
}

form button:hover {
    background-color: #4cae4c;
}

/* Notes list styling */
.notes {
    list-style: none;
    padding: 0;
}

.notes li {
    background: #f4f4f4;
    margin: 10px 0;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 4px;
}

.notes li h2 {
    margin: 0 0 5px;
    font-size: 1.5em;
    color: #555;
}

.notes li p {
    margin: 0;
    color: #666;
}

/* Footer styling */
footer {
    text-align: center;
    margin-top: 20px;
    font-size: 0.9em;
    color: #888;
}

